public final String readUtf(int constantPoolEntryIndex, char[] charBuffer) {
    ConstUtf8 constUtf8 = getConstantEntry(constantPoolEntryIndex);
    if (constUtf8 == null || !constUtf8.isResolved()) {
        return null;
    }
    byte[] utf8Bytes = new byte[constUtf8.getLength()];
    read(utf8Bytes, 0, constUtf8.getLength());
    int offset = 0;
    while (offset < utf8Bytes.length) {
        char character = (char) (utf8Bytes[offset] & 0xFF);
        if (character == '\0') {
            break;
        }
        charBuffer[offset++] = character;
    }
    return new String(charBuffer, 0, offset);
}

