public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Ensure the box is not null
    if (box == null) {
        throw new IllegalArgumentException("Box cannot be null");
    }

    // Calculate the midpoint of the box's x-coordinate
    double midpointX = box.getX() + box.getWidth() / 2.0;

    // Create two new boxes, each covering half of the original box
    Box2D firstBox = new Box2D(box.getX(), box.getY(), midpointX, box.getHeight());
    Box2D secondBox = new Box2D(midpointX, box.getY(), box.getX() + box.getWidth(), box.getHeight());

    return new Pair<>(firstBox, secondBox);
}

