public static long compressTimeBucket(long timeBucket, int dayStep) {
    // Calculate the new interval based on dayStep
    long newInterval = timeBucket / dayStep;

    // Format the time bucket by stripping off any parts that are not part of the new interval
    long formattedTimeBucket = timeBucket % dayStep;

    // If the formatted time bucket is zero, it means we need to include the previous interval
    if (formattedTimeBucket == 0) {
        formattedTimeBucket = newInterval - 1;
    }

    return (long) newInterval * dayStep + formattedTimeBucket;
}

