public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    if (null == str) return 0;

    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if ((c >> 5) == 0) { // 1-byte characters
            size += 1;
        } else if ((c >> 4) == 0x6) { // 2-byte characters
            size += 2;
        } else if ((c >> 3) == 0xe) { // 3-byte characters
            size += 3;
        } else if ((c >> 2) == 0xf) { // 4-byte characters
            size += 4;
        }
    }

    return size;
}

